const HEADING = 'h1, h2, h3, .mmc-section-eyebrow, .mmc-eyebrow, .mmc-label, .section-title, [class*="-head"], .mmc-blog-hero, .mmc-pricing-head, .mmc-contact-head, .mmc-c10-head, .mmc-offer-head, .mmc-rev-head';
const CTA = '.btn, .mmc-why-cta, .mmc-hero-cta, .mmc-hero-ghost, .mmc-about-btn, .mmc-price-cta, .mmc-auth-submit, [class*="-cta"]';
const VISUAL = '[class*="-visual"], [class*="spline"], [class*="-featured"], .mmc-svc-hub, .mmc-price-card--featured, .mmc-ca-video-card, .mmc-auth-card, .mmc-stats-item.is-accent';

export function inferRevealVariant(el, role) {
  if (!el || typeof window === 'undefined') return 'up';
  if (role === 'heading') return 'down';
  if (role === 'cta') return 'up';
  if (role === 'visual') return 'scale';
  if (role === 'float') return 'down';

  try {
    if (el.matches(HEADING)) return 'down';
    if (el.matches(CTA)) return 'up';
    if (el.matches(VISUAL)) return 'scale';
  } catch {
    /* ignore invalid selectors on older engines */
  }

  const rect = el.getBoundingClientRect();
  const vw = Math.max(window.innerWidth, 1);
  const ratio = (rect.left + rect.width * 0.5) / vw;

  if (rect.width > vw * 0.74) return 'scale';
  if (ratio < 0.38) return 'left';
  if (ratio > 0.62) return 'right';
  return 'up';
}

export function staggerDelay(index, step = 65, base = 0) {
  return base + index * step;
}
